css:
.n4-preset-card {
  --preset-text: var(--n4-color-text, #0f172a);
  --preset-muted: var(--n4-color-muted, #64748b);
  --preset-border: var(--n4-color-border, #e2e8f0);
  --preset-primary: var(--n4-color-primary, #0d9488);
  display: flex; flex-direction: column; height: 100%; min-width: 0; box-sizing: border-box;
  padding: 16px; border: 1px solid var(--preset-border); border-radius: 8px;
  background: var(--n4-color-surface, #fff); color: var(--preset-text); line-height: 1.5;
  font-family: var(--n4-font-sans, Inter, system-ui, sans-serif);
}
.n4-preset-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; margin-bottom: 12px; flex-wrap: wrap; }
.n4-preset-template { display: flex; align-items: center; gap: 8px; padding: 2px 8px; border-radius: 4px; background: #06b6d41a; color: #0891b2; font-size: 12px; font-weight: 500; }
.n4-preset-name { font: 600 16px/1.5 var(--n4-font-sans, Inter, system-ui, sans-serif); margin: 0; color: inherit; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.n4-preset-description { font-size: 11px; color: var(--preset-muted); margin: 4px 0 0; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
.n4-preset-hint { display: flex; align-items: center; gap: 6px; margin-top: 8px; font-size: 11px; color: var(--preset-muted); }
.n4-preset-stats { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 8px; padding: 8px 12px; margin: 12px 0 0; border: 1px solid var(--preset-border); border-radius: 6px; background: color-mix(in srgb, var(--preset-muted) 4%, transparent); }
.n4-preset-stats dd { margin: 0; font-size: 14px; font-weight: 600; font-variant-numeric: tabular-nums; line-height: 1; overflow-wrap: anywhere; }
.n4-preset-stats dt { font-size: 10px; margin-top: 2px; text-transform: uppercase; letter-spacing: .025em; color: var(--preset-muted); }
.n4-preset-stats .n4-preset-emphasize { font-size: clamp(12px, 1vw, 14px); white-space: nowrap; color: var(--preset-primary); }
.n4-preset-preview { padding: 0; margin: 12px 0 0; list-style: none; font-size: 12px; }
.n4-preset-preview li { display: flex; align-items: center; gap: 8px; min-width: 0; margin-top: 4px; color: var(--preset-muted); }
.n4-preset-preview li > span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.n4-preset-preview svg, .n4-preset-header svg, .n4-preset-hint svg { width: 12px; height: 12px; flex-shrink: 0; }
.n4-preset-preview .n4-preset-more { font-size: 11px; font-style: italic; }
.n4-preset-actions { display: flex; gap: 8px; margin-top: auto; padding-top: 12px; }
.n4-preset-actions > div { flex: 1; min-width: 0; }
.n4-preset-action { display: flex; justify-content: center; align-items: center; box-sizing: border-box; width: 100%; min-height: 32px; padding: 4px 12px; border: 1px solid #10b98140; border-radius: 999px; background: #10b9811a; color: #047857; font-size: 11px; font-weight: 600; text-decoration: none; }
.n4-preset-action:hover { background: #10b98129; text-decoration: none; }
.n4-preset-action-classification { border-color: #0ea5e940; background: #0ea5e91a; color: #0369a1; }
.n4-preset-action-classification:hover { background: #0ea5e929; }
.n4-preset-complexity { display: inline-flex; align-items: center; gap: 6px; border: 1px solid; padding: 4px 10px; border-radius: 999px; font-size: 11px; font-weight: 600; }
.n4-preset-complexity > span { text-transform: capitalize; }
.n4-preset-starter { color: #047857; border-color: #10b98140; background: #10b9811a; }
.n4-preset-quick { color: #0369a1; border-color: #0ea5e940; background: #0ea5e91a; }
.n4-preset-balanced { color: #b45309; border-color: #f59e0b40; background: #f59e0b1a; }
.n4-preset-heavy { color: #c2410c; border-color: #f9731640; background: #f973161a; }
.n4-preset-exhaustive { color: #be123c; border-color: #f43f5e40; background: #f43f5e1a; }
.n4-preset-action:focus-visible { outline: 2px solid var(--preset-primary, #0d9488); outline-offset: 3px; }
